34	// Config store any configuration required to make the tests run
35	type Config struct {
36		// Port we expect caddy to listening on
37		AdminPort int
38		// Certificates we expect to be loaded before attempting to run the tests
39		Certificates []string
40		// TestRequestTimeout is the time to wait for a http request to
41		TestRequestTimeout time.Duration
42		// LoadRequestTimeout is the time to wait for the config to be loaded against the caddy server
43		LoadRequestTimeout time.Duration
44	}
45	
46	// Default testing values
47	var Default = Config{
48		AdminPort:          2999, // different from what a real server also running on a developer's machine might be
49		Certificates:       []string{"/caddy.localhost.crt", "/caddy.localhost.key"},
50		TestRequestTimeout: 5 * time.Second,
51		LoadRequestTimeout: 5 * time.Second,
52	}
