432		// prettify results to keep tests human-manageable
433		var prettyBuf bytes.Buffer
434		err = json.Indent(&prettyBuf, result, "", "\t")
435		if err != nil {
436			return false
437		}
438		result = prettyBuf.Bytes()
439	
440		if len(warnings) > 0 {
441			for _, w := range warnings {
442				t.Logf("warning: %s:%d: %s: %s", filename, w.Line, w.Directive, w.Message)
443			}
444		}
445	
446		diff := difflib.Diff(
447			strings.Split(expectedResponse, "\n"),
448			strings.Split(string(result), "\n"))
449	
450		// scan for failure
451		failed := false
452		for _, d := range diff {
453			if d.Delta != difflib.Common {
454				failed = true
455				break
456			}
457		}
458	
459		if failed {
460			for _, d := range diff {
461				switch d.Delta {
462				case difflib.Common:
463					fmt.Printf("  %s\n", d.Payload)
464				case difflib.LeftOnly:
465					fmt.Printf(" - %s\n", d.Payload)
466				case difflib.RightOnly:
467					fmt.Printf(" + %s\n", d.Payload)
468				}
469			}
470			return false
471		}
472		return true
473	}
