19	
20	const caddyBinaryName = "caddy"
21	
22	// repoRoot is the repository root (the test binary runs in
23	// caddytest/integration).
24	func repoRoot(t *testing.T) string {
25		t.Helper()
26		root, err := filepath.Abs(filepath.Join("..", ".."))
27		if err != nil {
28			t.Fatal(err)
29		}
30		return root
31	}
32	
33	// binaryName returns the platform-specific caddy binary name.
34	func binaryName() string {
35		if runtime.GOOS == "windows" {
36			return caddyBinaryName + ".exe"
37		}
38		return caddyBinaryName
39	}
40	
41	// adminHostPort extracts the host:port from an admin endpoint URL.
42	func adminHostPort(adminURL string) string {
43		u, err := url.Parse(adminURL)
44		if err != nil {
45			return strings.TrimPrefix(adminURL, "http://")
46		}
47		return u.Host
48	}
49	
50	// This file verifies that the reverse_proxy failover state stays isolated
51	// across the strongest possible boundary: a full process restart reusing the
52	// exact same listen address. The request-boundary matrix (retry budgets,
53	// deadlines, bodies, headers and upstream counters never leaking between
54	// requests in one process) lives in reverseproxy_failover_test.go; here a
55	// real `caddy` binary is built, started, stopped cleanly and restarted on the
56	// same ports, so the upstream counters - which live in the test process and
57	// therefore survive every caddy restart - can prove that no retry budget,
58	// deadline, request body or response state crosses a process boundary.
59	
60	// caddyInstance is one running `caddy run` subprocess.
61	type caddyInstance struct {
62		cmd       *exec.Cmd
63		logPath   string
64		waitDone  chan error
65		adminURL  string
66		stoppedMu sync.Mutex
67		stopped   bool
68	}
69	
70	// buildCaddyBinary compiles the in-tree cmd/caddy binary once and returns its
71	// path. The subprocess must contain the standard modules (Caddyfile adapter,
72	// reverse_proxy, file storage, internal TLS), which cmd/caddy imports.
73	func buildCaddyBinary(t *testing.T) string {
74		t.Helper()
75		if testing.Short() {
76			t.Skip("skipping cross-process restart test in short mode")
77		}
78		if _, err := exec.LookPath("go"); err != nil {
79			t.Skipf("go toolchain unavailable: %v", err)
80		}
81	
82		bin := filepath.Join(t.TempDir(), binaryName())
83		build := exec.Command("go", "build", "-o", bin, "./cmd/caddy")
84		build.Dir = repoRoot(t)
85		var buildErr bytes.Buffer
86		build.Stderr = &buildErr
87		if err := build.Run(); err != nil {
88			t.Fatalf("building caddy binary: %v\n%s", err, buildErr.String())
89		}
90		return bin
91	}
92	
93	// isolatedCaddyEnv gives the subprocess its own HOME/XDG/AppData roots under
94	// runDir, so the internal CA, autosave and locks never touch the developer
95	// machine and never bleed between (failed) starts.
96	func isolatedCaddyEnv(runDir, suffix string) []string {
97		root := filepath.Join(runDir, suffix)
98		home := filepath.Join(root, "home")
99		env := os.Environ()
100		if runtime.GOOS == "windows" {
101			env = append(env,
102				"USERPROFILE="+home,
103				"APPDATA="+filepath.Join(root, "appdata"),
104				"LOCALAPPDATA="+filepath.Join(root, "localappdata"),
105			)
106		} else {
107			env = append(env,
108				"HOME="+home,
109				"XDG_DATA_HOME="+filepath.Join(root, "data"),
110				"XDG_CONFIG_HOME="+filepath.Join(root, "config"),
111				"XDG_STATE_HOME="+filepath.Join(root, "state"),
112			)
113		}
114		return env
115	}
116	
117	// writeRestartCaddyConfig writes the Caddyfile used across a whole restart
118	// matrix: a fixed admin address, a zero grace period (so a stopped process
119	// releases its sockets promptly) and the given site block.
120	func writeRestartCaddyConfig(t *testing.T, dir, name, adminAddr, siteBlock string) string {
121		t.Helper()
122		cfg := fmt.Sprintf(`
123		{
124			skip_install_trust
125			admin %s
126			grace_period 1ns
127		}
128		%s
129		`, adminAddr, siteBlock)
130		cfgPath := filepath.Join(dir, name)
131		if err := os.WriteFile(cfgPath, []byte(cfg), 0o600); err != nil {
132			t.Fatalf("writing %s: %v", name, err)
133		}
134		return cfgPath
135	}
136	
137	// startCaddy launches `caddy run` with the given config and isolated data and
138	// config directories, then waits until the site answers a request. The
139	// returned instance must be stopped with stopCaddy.
140	func startCaddy(t *testing.T, bin, cfgPath, runDir, adminURL, readyURL string, h2 bool) *caddyInstance {
141		t.Helper()
142	
143		logFile, err := os.Create(filepath.Join(runDir, "caddy.log"))
144		if err != nil {
145			t.Fatalf("creating log file: %v", err)
146		}
147	
148		cmd := exec.Command(bin, "run", "--config", cfgPath, "--adapter", "caddyfile")
149		cmd.Stdout = logFile
150		cmd.Stderr = logFile
151		// isolate every on-disk artifact (autosave, internal CA, locks) from the
152		// developer machine and from other test runs
153		cmd.Env = isolatedCaddyEnv(runDir, "state")
154		if err := cmd.Start(); err != nil {
155			logFile.Close()
156			t.Fatalf("starting caddy: %v", err)
157		}
158	
159		inst := &caddyInstance{
160			cmd:      cmd,
161			logPath:  logFile.Name(),
162			waitDone: make(chan error, 1),
163			adminURL: adminURL,
164		}
165		go func() { inst.waitDone <- cmd.Wait(); logFile.Close() }()
166	
167		inst.waitReady(t, readyURL, h2)
168		return inst
169	}
170	
171	// startCaddyExpectingFailure launches `caddy run` with a configuration that
172	// cannot be loaded and asserts the process exits unsuccessfully on its own,
173	// leaving no half-alive instance: nothing must be accepting requests on the
174	// site port afterwards.
175	func startCaddyExpectingFailure(t *testing.T, bin, cfgPath, runDir, siteHostPort string) {
176		t.Helper()
177	
178		logFile, err := os.Create(filepath.Join(runDir, "caddy-failed.log"))
179		if err != nil {
180			t.Fatalf("creating log file: %v", err)
181		}
182		cmd := exec.Command(bin, "run", "--config", cfgPath, "--adapter", "caddyfile")
183		cmd.Stdout = logFile
184		cmd.Stderr = logFile
185		cmd.Env = isolatedCaddyEnv(runDir, "state-fail")
186		if err := cmd.Start(); err != nil {
187			logFile.Close()
188			t.Fatalf("starting caddy: %v", err)
189		}
190	
191		waitErr := make(chan error, 1)
192		go func() { waitErr <- cmd.Wait(); logFile.Close() }()
193	
194		select {
195		case err := <-waitErr:
196			if err == nil {
197				t.Fatalf("caddy with an invalid config exited successfully; want a nonzero exit")
198			}
199		case <-time.After(30 * time.Second):
200			_ = cmd.Process.Kill()
201			t.Fatalf("caddy with an invalid config did not exit; a failed startup left a live process")
202		}
203	
204		// the failed instance must not be serving: the site port must refuse
205		// connections rather than be held by a half-alive process
206		conn, dialErr := net.DialTimeout("tcp", siteHostPort, time.Second)
207		if dialErr == nil {
208			conn.Close()
209			t.Fatalf("site port %s is still accepting connections after a failed startup", siteHostPort)
210		}
211	}
212	
213	// waitReady polls the site until a fully successful request is served, proving
214	// the new instance (and only it) owns the listen address.
215	func (p *caddyInstance) waitReady(t *testing.T, readyURL string, h2 bool) {
216		t.Helper()
217		client := newFailoverClient(h2)
218		deadline := time.Now().Add(60 * time.Second)
219		for time.Now().Before(deadline) {
220			select {
221			case err := <-p.waitDone:
222				t.Fatalf("caddy exited before becoming ready: %v\n%s", err, p.tailLog())
223			default:
224			}
225			resp, err := client.Get(readyURL + "/ok")
226			if err == nil {
227				_, _ = io.Copy(io.Discard, resp.Body)
228				resp.Body.Close()
229				if resp.StatusCode == http.StatusOK {
230					return
231				}
232			}
233			time.Sleep(50 * time.Millisecond)
234		}
235		t.Fatalf("caddy did not become ready within 60s\n%s", p.tailLog())
236	}
237	
238	// stopCaddy asks the instance to shut down cleanly through its admin API and
239	// waits for the process to actually exit, so the same address can be rebound
240	// and no residual process can serve the next instance's traffic.
241	func (p *caddyInstance) stopCaddy(t *testing.T) {
242		t.Helper()
243		p.stoppedMu.Lock()
244		if p.stopped {
245			p.stoppedMu.Unlock()
246			return
247		}
248		p.stopped = true
249		p.stoppedMu.Unlock()
250	
251		// the connection may be cut as the process exits mid-response; that is
252		// expected, so a POST error is not fatal as long as the process exits
253		if resp, err := http.Post(p.adminURL+"/stop", "application/json", nil); err == nil {
254			resp.Body.Close()
255		}
256	
257		select {
258		case err := <-p.waitDone:
259			if err != nil {
260				t.Fatalf("caddy stopped unsuccessfully: %v\n%s", err, p.tailLog())
261			}
262		case <-time.After(30 * time.Second):
263			_ = p.cmd.Process.Kill()
264			t.Fatalf("caddy did not exit within 30s of a clean stop")
265		}
266	}
267	
268	func (p *caddyInstance) tailLog() string {
269		b, err := os.ReadFile(p.logPath)
270		if err != nil {
271			return fmt.Sprintf("(unreadable log %s: %v)", p.logPath, err)
272		}
273		const max = 4000
274		if len(b) > max {
275			b = b[len(b)-max:]
276		}
277		return string(b)
278	}
