280	// restartRound is one full restart cycle: stop the previous instance
281	// (if any), immediately start a new one with the same config on the same
282	// listen address, then run a complete request matrix whose bodies are unique
283	// to this round. All assertions are deltas against the test-process upstream
284	// counters, which survive the caddy restart, so any inherited retry budget,
285	// body or response header would be detected.
286	type restartRound struct {
287		number int
288		body   string
289		query  string
290		trace  string
291	}
292	
293	func runRestartRound(t *testing.T, bin, cfgPath, runDir, adminURL, baseURL string, h2 bool, wantProto int,
294		first, backup *failoverUpstream, prev *caddyInstance, rd restartRound,
295	) *caddyInstance {
296		t.Helper()
297	
298		if prev != nil {
299			prev.stopCaddy(t)
300			// the stopped process must not be lingering on its admin port
301			if conn, err := net.DialTimeout("tcp", adminHostPort(adminURL), 500*time.Millisecond); err == nil {
302				conn.Close()
303				t.Fatalf("admin port still accepting connections after clean stop")
304			}
305		}
306	
307		// restart immediately with the same configuration and the same listen
308		// address; this must bind successfully and must not race a zombie
309		inst := startCaddy(t, bin, cfgPath, runDir, adminURL, baseURL, h2)
310	
311		client := newFailoverClient(h2)
312	
313		// POST: first node dies before the final response; the backup must see
314		// exactly this round's request, byte for byte, exactly once - not the body
315		// or query of a previous round and not more than one attempt.
316		t.Run(fmt.Sprintf("round%d POST failover exact replay", rd.number), func(t *testing.T) {
317			baseFirst := first.hitCount("/retry-before")
318			baseRecs := len(backup.recordings("/retry-before"))
319	
320			req, err := http.NewRequest(http.MethodPost, baseURL+"/retry-before?"+rd.query, strings.NewReader(rd.body))
321			if err != nil {
322				t.Fatal(err)
323			}
324			req.Header.Set("Content-Type", "application/json")
325			req.Header.Set("X-Trace", rd.trace)
326	
327			resp, interim, _ := tracedDo(t, client, req)
328			gotBody, readErr := io.ReadAll(resp.Body)
329			resp.Body.Close()
330			requireBackupFinalResponse(t, resp, interim, gotBody, readErr, wantProto, "ok201")
331	
332			if got := first.hitCount("/retry-before") - baseFirst; got != 1 {
333				t.Errorf("first upstream hits: got %d new, want 1", got)
334			}
335			requireExactReplay(t, backup, "/retry-before", baseRecs, recordedRequest{
336				method:        http.MethodPost,
337				rawQuery:      rd.query,
338				contentLength: int64(len(rd.body)),
339				contentType:   "application/json",
340				xTrace:        rd.trace,
341				body:          []byte(rd.body),
342			})
343		})
344	
345		// GET and HEAD fail over the same way; HEAD returns no body but keeps the
346		// GET length semantics, and every method reaches the backup exactly once.
347		t.Run(fmt.Sprintf("round%d GET failover", rd.number), func(t *testing.T) {
348			baseFirst := first.hitCount("/retry-before")
349			baseRecs := len(backup.recordings("/retry-before"))
350	
351			resp, interim, _ := tracedDo(t, client, mustNewRequest(t, http.MethodGet, baseURL+"/retry-before"))
352			gotBody, readErr := io.ReadAll(resp.Body)
353			resp.Body.Close()
354			requireBackupFinalResponse(t, resp, interim, gotBody, readErr, wantProto, "ok201")
355			if got := first.hitCount("/retry-before") - baseFirst; got != 1 {
356				t.Errorf("first upstream hits: got %d new, want 1", got)
357			}
358			requireExactReplay(t, backup, "/retry-before", baseRecs, recordedRequest{method: http.MethodGet})
359		})
360	
361		t.Run(fmt.Sprintf("round%d HEAD failover length semantics", rd.number), func(t *testing.T) {
362			baseFirst := first.hitCount("/retry-before")
363			baseRecs := len(backup.recordings("/retry-before"))
364	
365			resp, interim, _ := tracedDo(t, client, mustNewRequest(t, http.MethodHead, baseURL+"/retry-before"))
366			gotBody, readErr := io.ReadAll(resp.Body)
367			resp.Body.Close()
368			requireBackupFinalResponse(t, resp, interim, gotBody, readErr, wantProto, "")
369			if got := first.hitCount("/retry-before") - baseFirst; got != 1 {
370				t.Errorf("first upstream hits: got %d new, want 1", got)
371			}
372			requireExactReplay(t, backup, "/retry-before", baseRecs, recordedRequest{method: http.MethodHead})
373		})
374	
375		// interim 103 then failure: ordering is preserved after a restart too.
376		t.Run(fmt.Sprintf("round%d interim then failover", rd.number), func(t *testing.T) {
377			baseBackup := backup.hitCount("/retry-info")
378	
379			resp, interim, _ := tracedDo(t, client, mustNewRequest(t, http.MethodGet, baseURL+"/retry-info"))
380			body, readErr := io.ReadAll(resp.Body)
381			resp.Body.Close()
382			requireProtocol(t, resp, wantProto)
383			if len(interim) != 1 || interim[0].code != http.StatusEarlyHints {
384				t.Fatalf("interim responses: got %v, want a single 103", interim)
385			}
386			if resp.StatusCode != http.StatusCreated || string(body) != "ok201" || readErr != nil {
387				t.Fatalf("got %d %q (err=%v), want 201 ok201 clean", resp.StatusCode, body, readErr)
388			}
389			if got := backup.hitCount("/retry-info") - baseBackup; got != 1 {
390				t.Errorf("backup upstream hits: got %d new, want 1", got)
391			}
392		})
393	
394		// the first node answers successfully: fixed order is preserved and the
395		// backup is never contacted, in every round.
396		t.Run(fmt.Sprintf("round%d first node success keeps order", rd.number), func(t *testing.T) {
397			baseBackup := backup.hitCount("/ok")
398	
399			resp, interim, _ := tracedDo(t, client, mustNewRequest(t, http.MethodGet, baseURL+"/ok"))
400			body, readErr := io.ReadAll(resp.Body)
401			resp.Body.Close()
402			requireProtocol(t, resp, wantProto)
403			if len(interim) != 0 {
404				t.Errorf("interim responses: got %v, want none", interim)
405			}
406			if resp.StatusCode != http.StatusOK || string(body) != "ok" || readErr != nil {
407				t.Fatalf("got %d %q (err=%v), want 200 ok clean", resp.StatusCode, body, readErr)
408			}
409			if got := backup.hitCount("/ok") - baseBackup; got != 0 {
410				t.Errorf("backup must not be contacted when the first node succeeds after a restart, got %d new hits", got)
411			}
412		})
413	
