415		// body): that response must be kept and never spliced with the backup.
416		t.Run(fmt.Sprintf("round%d final response not spliced with backup", rd.number), func(t *testing.T) {
417			baseFirst := first.hitCount("/partial")
418			baseBackup := backup.hitCount("/partial")
419	
420			resp, interim, _ := tracedDo(t, client, mustNewRequest(t, http.MethodGet, baseURL+"/partial"))
421			body, readErr := io.ReadAll(resp.Body)
422			resp.Body.Close()
423			requireProtocol(t, resp, wantProto)
424			if len(interim) != 0 {
425				t.Errorf("interim responses: got %v, want none", interim)
426			}
427			if resp.StatusCode != http.StatusOK {
428				t.Fatalf("status: got %d, want 200 from the first node", resp.StatusCode)
429			}
430			if resp.Header.Get("X-Origin") != "first" {
431				t.Errorf("X-Origin: got %q, want first (no backup splicing)", resp.Header.Get("X-Origin"))
432			}
433			if !bytes.HasPrefix(body, []byte("part1")) {
434				t.Errorf("body: got %q, want the first node's part1 prefix", body)
435			}
436			if readErr == nil {
437				t.Errorf("expected a truncated transfer error, got a clean read")
438			}
439			if got := first.hitCount("/partial") - baseFirst; got != 1 {
440				t.Errorf("first upstream hits: got %d new, want 1", got)
441			}
442			if got := backup.hitCount("/partial") - baseBackup; got != 0 {
443				t.Errorf("backup must not be retried after a final response across a restart, got %d new hits", got)
444			}
445		})
446	
447		// both nodes fail: still a single clean gateway error, no leaked node data.
448		t.Run(fmt.Sprintf("round%d both fail single 502", rd.number), func(t *testing.T) {
449			baseFirst := first.hitCount("/all-fail")
450			baseBackup := backup.hitCount("/all-fail")
451	
452			resp, interim, _ := tracedDo(t, client, mustNewRequest(t, http.MethodGet, baseURL+"/all-fail"))
453			body, readErr := io.ReadAll(resp.Body)
454			resp.Body.Close()
455			requireProtocol(t, resp, wantProto)
456			if len(interim) != 2 {
457				t.Errorf("interim responses: got %v, want the two 103s in order", interim)
458			}
459			if resp.StatusCode != http.StatusBadGateway {
460				t.Fatalf("status: got %d, want 502", resp.StatusCode)
461			}
462			if readErr != nil {
463				t.Errorf("502 body should read cleanly: %v", readErr)
464			}
465			if h := resp.Header.Get("X-Origin"); h != "" {
466				t.Errorf("failed node header X-Origin leaked: %q", h)
467			}
468			if bytes.Contains(body, []byte("part1")) {
469				t.Errorf("502 body contains an upstream fragment: %q", body)
470			}
471			if got := first.hitCount("/all-fail") - baseFirst; got != 1 {
472				t.Errorf("first upstream hits: got %d new, want 1", got)
473			}
474			if got := backup.hitCount("/all-fail") - baseBackup; got != 1 {
475				t.Errorf("backup upstream hits: got %d new, want 1", got)
476			}
477		})
478	
479		// retries explicitly disabled for this route: the backup must never be
480		// contacted for it, in any round, before or after any restart.
481		t.Run(fmt.Sprintf("round%d no-retry never reaches backup", rd.number), func(t *testing.T) {
482			baseFirst := first.hitCount("/no-retry")
483			baseBackup := backup.hitCount("/no-retry")
484	
485			req, err := http.NewRequest(http.MethodPost, baseURL+"/no-retry?z=9", strings.NewReader(rd.body))
486			if err != nil {
487				t.Fatal(err)
488			}
489			req.Header.Set("Content-Type", "application/json")
490	
491			resp, interim, _ := tracedDo(t, client, req)
492			body, readErr := io.ReadAll(resp.Body)
493			resp.Body.Close()
494			requireProtocol(t, resp, wantProto)
495			if len(interim) != 0 {
496				t.Errorf("interim responses: got %v, want none", interim)
497			}
498			if resp.StatusCode != http.StatusBadGateway {
499				t.Fatalf("status: got %d, want 502", resp.StatusCode)
500			}
501			if readErr != nil {
502				t.Errorf("502 body should read cleanly: %v", readErr)
503			}
504			if bytes.Contains(body, []byte(rd.body)) {
505				t.Errorf("502 body must not contain the request body: %q", body)
506			}
507			if got := first.hitCount("/no-retry") - baseFirst; got != 1 {
508				t.Errorf("first upstream hits: got %d new, want 1", got)
509			}
510			if got := backup.hitCount("/no-retry") - baseBackup; got != 0 {
511				t.Errorf("backup must not be contacted on /no-retry after a restart, got %d new hits", got)
512			}
513		})
514	
515		return inst
516	}
517	
518	// TestReverseProxyFailoverAcrossProcessRestarts drives the complete
519	// stop/restart matrix on a real caddy binary for plaintext HTTP/1.1 and TLS
520	// HTTP/2 sites. The two upstreams live in the test process and outlive every
521	// caddy restart, so their cumulative counters prove that each restart starts
522	// from zero: each round has its own distinct body, and the backup may observe
523	// exactly one copy of that round's request per failover - never a previous
524	// round's body/query, never a spent retry budget, and never a response from a
525	// failed node.
526	func TestReverseProxyFailoverAcrossProcessRestarts(t *testing.T) {
527		bin := buildCaddyBinary(t)
528	
529		for _, tc := range []struct {
530			name         string
531			siteAddr     string // host:port of the caddy site
532			siteHead     string // site block header line
533			adminAddr    string // admin endpoint listen address
534			adminURL     string
535			h2           bool
536			wantProto    int
537			siteHostPort string
538		}{
539			{
540				name:         "HTTP/1.1",
541				siteAddr:     "127.0.0.1:9086",
542				siteHead:     "http://127.0.0.1:9086",
543				adminAddr:    "127.0.0.1:2998",
544				adminURL:     "http://127.0.0.1:2998",
545				h2:           false,
546				wantProto:    1,
547				siteHostPort: "127.0.0.1:9086",
548			},
549			{
550				name:         "HTTP/2 over TLS",
551				siteAddr:     "localhost:9449",
552				siteHead:     "https://localhost:9449",
553				adminAddr:    "127.0.0.1:2997",
554				adminURL:     "http://127.0.0.1:2997",
555				h2:           true,
556				wantProto:    2,
557				siteHostPort: "127.0.0.1:9449",
558			},
559		} {
560			t.Run(tc.name, func(t *testing.T) {
561				// fresh upstreams per protocol so the two matrices stay
562				// independent, yet shared across all restarts of this matrix
563				first := newFailoverUpstream(t, "first")
564				backup := newFailoverUpstream(t, "backup")
565	
566				runDir := t.TempDir()
567				baseURL := func() string {
568					if tc.h2 {
569						return "https://" + tc.siteAddr
570					}
571					return "http://" + tc.siteAddr
572				}()
573	
574				blocks := failoverSiteBlocks(first.addr(), backup.addr())
575				siteBlock := tc.siteHead + " {\n"
576				if tc.h2 {
577					siteBlock += "\ttls internal\n"
578				}
579				siteBlock += blocks + "\n}\n"
580				cfgPath := writeRestartCaddyConfig(t, runDir, "Caddyfile", tc.adminAddr, siteBlock)
581	
582				rounds := []restartRound{
583					{number: 1, body: `{"n":1}`, query: "a=1&b=2", trace: "t-7"},
584					{number: 2, body: `{"n":2}`, query: "a=2&b=3", trace: "t-8"},
585					{number: 3, body: `{"n":3}`, query: "a=3&b=4", trace: "t-9"},
586				}
587	
588				var inst *caddyInstance
589				t.Cleanup(func() {
590					if inst != nil {
591						inst.stopCaddy(t)
592					}
593				})
594				for _, rd := range rounds {
595					inst = runRestartRound(t, bin, cfgPath, runDir, tc.adminURL, baseURL, tc.h2, tc.wantProto,
596						first, backup, inst, rd)
597				}
598	
599				// after the last healthy round, a start with an unloadable
600				// configuration must fail on its own and leave nothing serving;
601				// the same address must then be bindable again by a healthy
602				// instance.
603				inst.stopCaddy(t)
604	
605				badCfg := filepath.Join(runDir, "Caddyfile.bad")
606				if err := os.WriteFile(badCfg, []byte(fmt.Sprintf(`
607				{
608					skip_install_trust
609					admin %s
610				}
611				%s {
612					this_directive_does_not_exist
613				}
614				`, tc.adminAddr, tc.siteHead)), 0o600); err != nil {
615					t.Fatalf("writing bad Caddyfile: %v", err)
616				}
617				startCaddyExpectingFailure(t, bin, badCfg, runDir, tc.siteHostPort)
618	
619				// the failed start must not have held onto the admin endpoint either
620				if conn, err := net.DialTimeout("tcp", adminHostPort(tc.adminURL), time.Second); err == nil {
621					conn.Close()
622					t.Fatalf("admin port still accepting connections after a failed startup")
623				}
624	
625				// the failed start poisoned nothing: the same config and address
626				// start again, and failover behaves exactly as in every other round
627				inst = startCaddy(t, bin, cfgPath, runDir, tc.adminURL, baseURL, tc.h2)
628				client := newFailoverClient(tc.h2)
629				func() {
630					baseRecs := len(backup.recordings("/retry-before"))
631					req, err := http.NewRequest(http.MethodPost, baseURL+"/retry-before?after=fail", strings.NewReader(`{"n":4}`))
632					if err != nil {
633						t.Fatal(err)
634					}
635					req.Header.Set("Content-Type", "application/json")
636					req.Header.Set("X-Trace", "t-10")
637					resp, interim, _ := tracedDo(t, client, req)
638					body, readErr := io.ReadAll(resp.Body)
639					resp.Body.Close()
640					requireBackupFinalResponse(t, resp, interim, body, readErr, tc.wantProto, "ok201")
641					requireExactReplay(t, backup, "/retry-before", baseRecs, recordedRequest{
642						method:        http.MethodPost,
643						rawQuery:      "after=fail",
644						contentLength: int64(len(`{"n":4}`)),
645						contentType:   "application/json",
646						xTrace:        "t-10",
647						body:          []byte(`{"n":4}`),
648					})
649				}()
650				inst.stopCaddy(t)
651			})
652		}
653	}
