	// success path is untouched
	resp, _, _ := tracedDo(t, client, mustNewRequest(t, http.MethodGet, "http://127.0.0.1:9082/ok"))
	body, _ := io.ReadAll(resp.Body)
	resp.Body.Close()
	if resp.StatusCode != http.StatusOK || string(body) != "ok" {
