177	// adaptByContentType adapts body to Caddy JSON using the adapter specified by contentType.
178	// If contentType is empty or ends with "/json", the input will be returned, as a no-op.
179	func adaptByContentType(contentType string, body []byte) ([]byte, []Warning, error) {
180		// assume JSON as the default
181		if contentType == "" {
182			return body, nil, nil
183		}
184	
185		ct, _, err := mime.ParseMediaType(contentType)
186		if err != nil {
187			return nil, nil, caddy.APIError{
188				HTTPStatus: http.StatusBadRequest,
189				Err:        fmt.Errorf("invalid Content-Type: %v", err),
190			}
