1	package integration
2	
3	import (
4		"crypto/tls"
5		"fmt"
6		"io"
7		"net"
8		"net/http"
9		"strings"
10		"sync"
11		"testing"
12		"time"
13	
14		"github.com/caddyserver/caddy/v2/caddytest"
15	)
16	
17	// This file verifies online configuration switching through the admin API's
18	// POST /load endpoint: a running site must move to a new configuration
19	// without disturbing requests that are already in flight, and a rejected
20	// configuration must leave the previous one serving untouched.
21	//
22	// Two configurations, A and B, share one listen address but answer /version
23	// with a different status, header and body. Config A's /hold route proxies
24	// to a test-controlled upstream that emits an A-marked prefix and then blocks
25	// until the test releases it by closing a control connection to the upstream.
26	// That gives the test a deterministic "request in flight across the switch"
27	// window: the prefix proves the response started on A, the switch is
28	// committed while the response is held, and the released response must then
29	// complete entirely with A's status, headers and body - never truncated,
30	// never duplicated, never mixed with B.
31	//
32	// The same matrix runs over plaintext HTTP/1.1 (JSON configs) and over
33	// HTTP/2 on an HTTPS listener configured with a Caddyfile using
34	// `tls internal`; the protocol must not change the switch boundary, the
35	// rollback on failure, or the in-flight response semantics.
36	
37	const (
38		// switchAdminAddr keeps the admin endpoint stable across every config
39		// loaded by these tests so the test never loses contact with the server
40		switchAdminAddr = "localhost:2999"
41	
42		// holdPrefix is flushed by the held upstream before it blocks;
43		// holdSuffix is written only after the test releases the hold
44		holdPrefix = "A-prefix;"
45		holdSuffix = "A-suffix;"
46	
47		// holdStatus is the distinctive status the held upstream responds with
48		holdStatus = 209
49	)
50	
51	// holdUpstream is a local HTTP server whose single endpoint writes an
52	// A-marked prefix, flushes, and then blocks until the test releases the
53	// response by closing a control connection to the upstream's gate listener.
54	// Each release closes the currently pending hold exactly once, and the hit
55	// counter lets the test prove a request reached the upstream exactly once.
56	type holdUpstream struct {
57		addr     string
58		gateAddr string
59	
60		mu      sync.Mutex
61		hits    int
62		pending chan struct{} // closed to release the currently held request
63	}
64	
65	func newHoldUpstream(t *testing.T) *holdUpstream {
66		t.Helper()
67	
68		httpLn, err := net.Listen("tcp", "127.0.0.1:0")
69		if err != nil {
70			t.Fatalf("listen for hold upstream: %v", err)
71		}
72		gateLn, err := net.Listen("tcp", "127.0.0.1:0")
73		if err != nil {
74			httpLn.Close()
75			t.Fatalf("listen for hold gate: %v", err)
76		}
77	
78		u := &holdUpstream{
79			addr: toHostPort(httpLn.Addr()),
80		}
81		u.gateAddr = toHostPort(gateLn.Addr())
82	
83		srv := &http.Server{Handler: http.HandlerFunc(u.serveHold)}
84		go func() { _ = srv.Serve(httpLn) }()
85	
86		// the gate listener accepts control connections from the test; when the
87		// test closes its connection the read side sees EOF and the currently
88		// held response is released
89		go func() {
90			for {
91				conn, err := gateLn.Accept()
92				if err != nil {
93					return
94				}
95				go func() {
96					_, _ = io.Copy(io.Discard, conn)
97					conn.Close()
98					u.release()
99				}()
100			}
101		}()
102	
103		t.Cleanup(func() {
104			srv.Close()
105			gateLn.Close()
106		})
107		return u
108	}
109	
110	// toHostPort normalizes a listener address to 127.0.0.1:port form so it can
111	// be embedded in a caddy config or dialed directly.
112	func toHostPort(addr net.Addr) string {
113		_, port, _ := net.SplitHostPort(addr.String())
114		return net.JoinHostPort("127.0.0.1", port)
115	}
116	
117	func (u *holdUpstream) serveHold(w http.ResponseWriter, r *http.Request) {
118		u.mu.Lock()
119		u.hits++
120		if u.pending == nil {
121			u.pending = make(chan struct{})
122		}
123		release := u.pending
124		u.mu.Unlock()
125	
126		w.Header().Set("X-Upstream-Mark", "A")
127		w.WriteHeader(holdStatus)
128		_, _ = io.WriteString(w, holdPrefix)
129		w.(http.Flusher).Flush()
130	
131		select {
132		case <-release:
133		case <-r.Context().Done():
134			// the downstream request went away while held; nothing to complete
135			return
136		}
137		_, _ = io.WriteString(w, holdSuffix)
138	}
139	
140	// release unblocks the currently held request, if any.
141	func (u *holdUpstream) release() {
142		u.mu.Lock()
143		defer u.mu.Unlock()
144		if u.pending != nil {
145			close(u.pending)
146			u.pending = nil
147		}
148	}
149	
150	func (u *holdUpstream) hitCount() int {
151		u.mu.Lock()
152		defer u.mu.Unlock()
153		return u.hits
154	}
155	
156	// holdSession is one in-flight /hold request plus the control connection
157	// that releases it.
158	type holdSession struct {
159		resp *http.Response
160		gate net.Conn
161	}
162	
163	// startHold issues a /hold request and blocks until the A-marked prefix has
164	// arrived, proving the response is in flight on the config that was active
165	// when the request started. The returned session must be completed with
166	// releaseAndAssertComplete.
167	func startHold(t *testing.T, client *http.Client, u *holdUpstream, baseURL string, wantProto int) *holdSession {
168		t.Helper()
169	
170		gate, err := net.DialTimeout("tcp", u.gateAddr, 5*time.Second)
171		if err != nil {
172			t.Fatalf("dialing hold gate: %v", err)
173		}
174	
175		respCh := make(chan *http.Response, 1)
176		errCh := make(chan error, 1)
177		go func() {
178			resp, err := client.Get(baseURL + "/hold")
179			if err != nil {
180				errCh <- err
181				return
182			}
183			respCh <- resp
184		}()
185	
186		var resp *http.Response
187		select {
188		case resp = <-respCh:
189		case err := <-errCh:
190			gate.Close()
191			t.Fatalf("GET /hold: %v", err)
192		case <-time.After(10 * time.Second):
193			gate.Close()
194			t.Fatal("GET /hold: timed out waiting for response headers")
195		}
196	
197		if resp.StatusCode != holdStatus {
198			t.Fatalf("held response status: got %d, want %d", resp.StatusCode, holdStatus)
199		}
200		if mark := resp.Header.Get("X-Upstream-Mark"); mark != "A" {
201			t.Fatalf("held response X-Upstream-Mark: got %q, want A", mark)
202		}
203		if resp.ProtoMajor != wantProto {
204			t.Fatalf("held response protocol: got HTTP/%d, want HTTP/%d", resp.ProtoMajor, wantProto)
205		}
206	
207		// the A-marked prefix must arrive while the upstream is still holding
208		// the rest of the response back
209		prefix := make([]byte, len(holdPrefix))
210		if _, err := io.ReadFull(resp.Body, prefix); err != nil {
211			gate.Close()
212			t.Fatalf("reading held prefix: %v", err)
213		}
214		if string(prefix) != holdPrefix {
215			t.Fatalf("held prefix: got %q, want %q", prefix, holdPrefix)
216		}
217	
218		return &holdSession{resp: resp, gate: gate}
219	}
220	
221	// releaseAndAssertComplete releases the held upstream by closing the control
222	// connection, then requires the in-flight response to finish cleanly with
223	// exactly the A-marked prefix and suffix - no truncation, no duplication, no
224	// content from any other config.
225	func (s *holdSession) releaseAndAssertComplete(t *testing.T) {
226		t.Helper()
227	
228		// release the held response by closing the control connection to the
229		// upstream
230		if err := s.gate.Close(); err != nil {
231			t.Fatalf("closing hold gate: %v", err)
232		}
233	
234		rest, err := io.ReadAll(s.resp.Body)
235		s.resp.Body.Close()
236		if err != nil {
237			t.Fatalf("held response did not complete cleanly after release: %v", err)
238		}
239		if got := holdPrefix + string(rest); got != holdPrefix+holdSuffix {
240			t.Fatalf("held response body: got %q, want exactly %q", got, holdPrefix+holdSuffix)
241		}
242	}
243	
244	// versionResponse identifies one config's /version answer.
245	type versionResponse struct {
246		status int
247		mark   string
248	}
249	
250	func (v versionResponse) body() string { return "config-" + v.mark }
251	
252	// assertVersion requires a single /version response to match the expected
253	// config exactly: status, marker header and body.
254	func assertVersion(t *testing.T, client *http.Client, baseURL string, want versionResponse, wantProto int) {
255		t.Helper()
256	
257		resp, err := client.Get(baseURL + "/version")
258		if err != nil {
259			t.Fatalf("GET /version: %v", err)
260		}
261		defer resp.Body.Close()
262		body, err := io.ReadAll(resp.Body)
263		if err != nil {
264			t.Fatalf("reading /version body: %v", err)
265		}
266	
267		if resp.ProtoMajor != wantProto {
268			t.Errorf("/version protocol: got HTTP/%d, want HTTP/%d", resp.ProtoMajor, wantProto)
269		}
270		if resp.StatusCode != want.status {
271			t.Errorf("/version status: got %d, want %d", resp.StatusCode, want.status)
272		}
273		if mark := resp.Header.Get("X-Config-Version"); mark != want.mark {
274			t.Errorf("/version X-Config-Version: got %q, want %q", mark, want.mark)
275		}
276		if string(body) != want.body() {
277			t.Errorf("/version body: got %q, want %q", body, want.body())
278		}
279	}
280	
281	// waitForVersion polls /version on fresh connections until the expected
282	// config answers, allowing the old server's listener handoff to settle; it
283	// fails if the new config does not take over promptly.
284	func waitForVersion(t *testing.T, v switchVariant, want versionResponse) {
285		t.Helper()
286	
287		client := newSwitchProbeClient(v.h2)
288		deadline := time.Now().Add(5 * time.Second)
289		for {
290			resp, err := client.Get(v.baseURL + "/version")
291			if err == nil {
292				body, _ := io.ReadAll(resp.Body)
293				mark := resp.Header.Get("X-Config-Version")
294				resp.Body.Close()
295				if resp.StatusCode == want.status && mark == want.mark && string(body) == want.body() {
296					return
297				}
298			}
299			if time.Now().After(deadline) {
300				t.Fatalf("config %s did not take over /version within 5s", want.mark)
301			}
302			time.Sleep(10 * time.Millisecond)
303		}
304	}
305	
306	// probeResult collects anomalies seen by a prober hammering /version across
307	// a config switch.
308	type probeResult struct {
309		mu        sync.Mutex
310		requests  int
311		retried   int
312		anomalies []string
313	}
314	
315	func (p *probeResult) record(format string, args ...any) {
316		p.mu.Lock()
317		defer p.mu.Unlock()
318		p.anomalies = append(p.anomalies, fmt.Sprintf(format, args...))
319	}
320	
321	func (p *probeResult) assertClean(t *testing.T, maxRetried int) {
322		t.Helper()
323		p.mu.Lock()
324		defer p.mu.Unlock()
325		if p.requests == 0 {
326			t.Error("prober issued no requests during the config load")
327		}
328		if p.retried > maxRetried {
329			t.Errorf("prober had to retry %d requests, want at most %d", p.retried, maxRetried)
330		}
331		for _, a := range p.anomalies {
332			t.Errorf("probe anomaly: %s", a)
333		}
334	}
335	
336	// probeDuringLoad hammers /version on fresh connections until stop is
337	// closed. Every response received must be a complete, consistent answer from
338	// one of the allowed configs - never a mix of one config's status with
339	// another's header or body. A transport error must be immediately retryable
340	// onto a consistent response; anything worse is an anomaly. This is what
341	// catches a transient no-config state or two instances answering at once.
342	func probeDuringLoad(v switchVariant, allowed []versionResponse, stop <-chan struct{}, p *probeResult, wg *sync.WaitGroup) {
343		defer wg.Done()
344	
345		client := newSwitchProbeClient(v.h2)
346		for {
347			select {
348			case <-stop:
349				return
350			default:
351			}
352	
353			resp, err := client.Get(v.baseURL + "/version")
354			if err != nil {
355				// during a successful switch the old server's accept loop can
356				// claim a connection in the handoff instant and have it closed
357				// by the stdlib shutdown path before it is served; an immediate
358				// retry must then land on a consistent config. Anything else is
359				// an anomaly.
360				p.mu.Lock()
361				p.retried++
362				p.mu.Unlock()
363				resp, err = client.Get(v.baseURL + "/version")
364				if err != nil {
365					p.record("transport error during load: %v", err)
366					continue
367				}
368			}
369			body, err := io.ReadAll(resp.Body)
370			mark := resp.Header.Get("X-Config-Version")
371			status := resp.StatusCode
372			resp.Body.Close()
373	
374			p.mu.Lock()
375			p.requests++
376			p.mu.Unlock()
377	
378			if err != nil {
379				p.record("body read error during load: %v", err)
380				continue
381			}
382			consistent := false
383			for _, a := range allowed {
384				if status == a.status && mark == a.mark && string(body) == a.body() {
385					consistent = true
386					break
387				}
388			}
389			if !consistent {
390				p.record("inconsistent response during load: status=%d mark=%q body=%q", status, mark, body)
391			}
392		}
393	}
394	
395	// switchVariant describes one protocol leg of the switch matrix.
396	type switchVariant struct {
397		name       string
398		configType string // "json" or "caddyfile"
399		baseURL    string
400		listenAddr string // listen address used by the invalid config
401		h2         bool
402		wantProto  int
403		config     func(mark string, status int, upstreamAddr string) string
404	}
405	
406	func switchVariants() []switchVariant {
407		return []switchVariant{
408			{
409				name:       "HTTP/1.1 plaintext JSON",
410				configType: "json",
411				baseURL:    "http://127.0.0.1:9088",
412				listenAddr: "127.0.0.1:9088",
413				h2:         false,
414				wantProto:  1,
415				config: func(mark string, status int, upstreamAddr string) string {
416					return jsonSwitchConfig("127.0.0.1:9088", mark, status, upstreamAddr)
417				},
418			},
419			{
420				name:       "HTTP/2 over TLS Caddyfile",
421				configType: "caddyfile",
422				baseURL:    "https://localhost:9451",
423				listenAddr: "127.0.0.1:9451",
424				h2:         true,
425				wantProto:  2,
426				config: func(mark string, status int, upstreamAddr string) string {
427					return caddyfileSwitchConfig("https://localhost:9451", mark, status, upstreamAddr)
428				},
429			},
430		}
431	}
432	
433	// jsonSwitchConfig is a complete JSON config for configs A and B: one server
434	// on the shared listen address answering /version with the given mark and
435	// proxying /hold to the test's upstream.
436	func jsonSwitchConfig(listenAddr, mark string, status int, upstreamAddr string) string {
437		return fmt.Sprintf(`{
438			"admin": {"listen": "%s"},
439			"apps": {
440				"http": {
441					"servers": {
442						"switch": {
443							"listen": ["%s"],
444							"routes": [
445								{
446									"match": [{"path": ["/version"]}],
447									"handle": [{
448										"handler": "static_response",
449										"status_code": %d,
450										"headers": {"X-Config-Version": ["%s"]},
451										"body": "config-%s"
452									}]
453								},
454								{
455									"match": [{"path": ["/hold"]}],
456									"handle": [{
457										"handler": "reverse_proxy",
458										"upstreams": [{"dial": "%s"}]
459									}]
460								}
461							]
462						}
463					}
464				}
465			}
466		}`, switchAdminAddr, listenAddr, status, mark, mark, upstreamAddr)
467	}
468	
469	// caddyfileSwitchConfig is the Caddyfile equivalent for the HTTPS leg, using
470	// `tls internal` for the localhost site.
471	func caddyfileSwitchConfig(siteAddr, mark string, status int, upstreamAddr string) string {
472		return fmt.Sprintf(`
473		{
474			skip_install_trust
475			admin %s
476		}
477		%s {
478			tls internal
479			handle /version {
480				header X-Config-Version %s
481				respond "config-%s" %d
482			}
483			handle /hold {
484				reverse_proxy %s
485			}
486		}
487		`, switchAdminAddr, siteAddr, mark, mark, status, upstreamAddr)
488	}
489	
490	// invalidSwitchConfig is a complete but unloadable JSON config: two HTTP
491	// servers claim the same listen address, which must be rejected while the
492	// running config keeps serving.
493	func invalidSwitchConfig(listenAddr string) string {
494		return fmt.Sprintf(`{
495			"admin": {"listen": "%s"},
496			"apps": {
497				"http": {
498					"servers": {
499						"first": {
500							"listen": ["%s"],
501							"routes": [{"handle": [{"handler": "static_response", "body": "one"}]}]
502						},
503						"second": {
504							"listen": ["%s"],
505							"routes": [{"handle": [{"handler": "static_response", "body": "two"}]}]
506						}
507					}
508				}
509			}
510		}`, switchAdminAddr, listenAddr, listenAddr)
511	}
512	
513	// postLoad submits a full config to the admin API's /load endpoint and
514	// returns the HTTP status and response body.
515	func postLoad(t *testing.T, rawConfig, configType string) (int, string) {
516		t.Helper()
517	
518		contentType := "application/json"
519		if configType != "json" {
520			contentType = "text/" + configType
521		}
522	
523		req, err := http.NewRequest(http.MethodPost, "http://"+switchAdminAddr+"/load", strings.NewReader(rawConfig))
524		if err != nil {
525			t.Fatalf("building /load request: %v", err)
526		}
527		req.Header.Set("Content-Type", contentType)
528	
529		resp, err := (&http.Client{Timeout: 30 * time.Second}).Do(req) //nolint:gosec // admin endpoint is hard-coded to localhost
530		if err != nil {
531			t.Fatalf("POST /load: %v", err)
532		}
533		defer resp.Body.Close()
534		body, err := io.ReadAll(resp.Body)
535		if err != nil {
536			t.Fatalf("reading /load response: %v", err)
537		}
538		return resp.StatusCode, string(body)
539	}
540	
541	// mustLoad submits a config that must be accepted.
542	func mustLoad(t *testing.T, rawConfig, configType string) {
543		t.Helper()
544		if code, body := postLoad(t, rawConfig, configType); code != http.StatusOK {
545			t.Fatalf("POST /load: got status %d, want 200; body: %s", code, body)
546		}
547	}
548	
549	// newSwitchClient builds a client for the held request and one-shot checks.
550	func newSwitchClient(h2 bool) *http.Client {
551		tr := &http.Transport{
552			DialContext:        (&net.Dialer{Timeout: 5 * time.Second}).DialContext,
553			DisableCompression: true,
554		}
555		if h2 {
556			tr.ForceAttemptHTTP2 = true
557			tr.TLSClientConfig = &tls.Config{InsecureSkipVerify: true} //nolint:gosec // test-only client
558		}
559		return &http.Client{Transport: tr, Timeout: 30 * time.Second}
560	}
561	
562	// newSwitchProbeClient builds a client that never reuses connections, so
563	// every request is accepted fresh by whichever config currently owns the
564	// listener.
565	func newSwitchProbeClient(h2 bool) *http.Client {
566		tr := &http.Transport{
567			DialContext:        (&net.Dialer{Timeout: 5 * time.Second}).DialContext,
568			DisableCompression: true,
569			DisableKeepAlives:  true,
570		}
571		if h2 {
572			tr.ForceAttemptHTTP2 = true
573			tr.TLSClientConfig = &tls.Config{InsecureSkipVerify: true} //nolint:gosec // test-only client
574		}
575		return &http.Client{Transport: tr, Timeout: 5 * time.Second}
576	}
577	
578	// TestConfigSwitchPreservesInFlightResponse runs the full switch matrix:
579	// a successful A->B switch with a request in flight, a rejected config that
580	// must roll back while B keeps serving, and a second successful switch back
581	// to A - proving the rounds stay isolated from each other.
582	func TestConfigSwitchPreservesInFlightResponse(t *testing.T) {
583		for _, v := range switchVariants() {
584			t.Run(v.name, func(t *testing.T) {
585				upstream := newHoldUpstream(t)
586				cfgA := v.config("A", 201, upstream.addr)
587				cfgB := v.config("B", 202, upstream.addr)
588				badCfg := invalidSwitchConfig(v.listenAddr)
589	
590				tester := caddytest.NewTester(t)
591				tester.InitServer(cfgA, v.configType)
592	
593				client := newSwitchClient(v.h2)
594				assertVersion(t, client, v.baseURL, versionResponse{status: 201, mark: "A"}, v.wantProto)
595	
596				// --- successful switch A->B with a request in flight ---
597				baseHits := upstream.hitCount()
598				hold := startHold(t, client, upstream, v.baseURL, v.wantProto)
599	
600				// while the switch commits, every /version response must be a
601				// complete A or B answer; the address must never go dark
602				stop := make(chan struct{})
603				probes := &probeResult{}
604				var wg sync.WaitGroup
605				wg.Add(1)
606				go probeDuringLoad(v, []versionResponse{{status: 201, mark: "A"}, {status: 202, mark: "B"}}, stop, probes, &wg)
607	
608				mustLoad(t, cfgB, v.configType)
609	
610				close(stop)
611				wg.Wait()
612				// a handful of retried connections is tolerable in the handoff
613				// instant; every response itself must have been consistent
614				probes.assertClean(t, 5)
615	
616				// after the commit, new requests on fresh connections are only
617				// ever answered by B: exactly one instance owns the address
618				waitForVersion(t, v, versionResponse{status: 202, mark: "B"})
619				for i := 0; i < 3; i++ {
620					assertVersion(t, newSwitchProbeClient(v.h2), v.baseURL, versionResponse{status: 202, mark: "B"}, v.wantProto)
621				}
622	
623				// release the upstream; the in-flight request must complete
624				// entirely with A's status, headers and body
625				hold.releaseAndAssertComplete(t)
626				if got := upstream.hitCount() - baseHits; got != 1 {
627					t.Errorf("upstream hits during A->B switch: got %d new, want 1", got)
628				}
629	
630				// --- failed switch: an invalid config is rejected and B keeps
631				// serving, including the request already in flight on B ---
632				baseHits = upstream.hitCount()
633				holdOnB := startHold(t, client, upstream, v.baseURL, v.wantProto)
634	
635				stopB := make(chan struct{})
636				probesB := &probeResult{}
637				wg.Add(1)
638				go probeDuringLoad(v, []versionResponse{{status: 202, mark: "B"}}, stopB, probesB, &wg)
639	
640				code, body := postLoad(t, badCfg, "json")
641	
642				close(stopB)
643				wg.Wait()
644	
645				if code == http.StatusOK {
646					t.Fatalf("invalid config with a repeated listener address was accepted")
647				}
648				if !strings.Contains(body, "listener address repeated") {
649					t.Errorf("load error does not report the repeated listener address: %q", body)
650				}
651				probesB.assertClean(t, 0)
652	
653				// B is still the only config serving; the in-flight request on B
654				// completes untouched by the rollback
655				assertVersion(t, newSwitchProbeClient(v.h2), v.baseURL, versionResponse{status: 202, mark: "B"}, v.wantProto)
656				holdOnB.releaseAndAssertComplete(t)
657				assertVersion(t, newSwitchProbeClient(v.h2), v.baseURL, versionResponse{status: 202, mark: "B"}, v.wantProto)
658				if got := upstream.hitCount() - baseHits; got != 1 {
659					t.Errorf("upstream hits during rejected load: got %d new, want 1", got)
660				}
661	
662				// --- second successful switch B->A: success, failure, success
663				// rounds must not leak requests, responses or errors into each
664				// other ---
665				baseHits = upstream.hitCount()
666				holdOnB2 := startHold(t, client, upstream, v.baseURL, v.wantProto)
667	
668				mustLoad(t, cfgA, v.configType)
669	
670				waitForVersion(t, v, versionResponse{status: 201, mark: "A"})
671				assertVersion(t, newSwitchProbeClient(v.h2), v.baseURL, versionResponse{status: 201, mark: "A"}, v.wantProto)
672	
673				holdOnB2.releaseAndAssertComplete(t)
674				if got := upstream.hitCount() - baseHits; got != 1 {
675					t.Errorf("upstream hits during B->A switch: got %d new, want 1", got)
676				}
677				assertVersion(t, newSwitchProbeClient(v.h2), v.baseURL, versionResponse{status: 201, mark: "A"}, v.wantProto)
678			})
679		}
680	}
681	
682	// TestConfigSwitchOrderingRegression pins down the ordering between commit
683	// completion, request release and rollback: a hold released before the new
684	// config is even submitted must complete on the config that started it, the
685	// subsequent commit must still take effect, and a rollback after everything
686	// has settled must leave the running config untouched. The rounds repeat so
687	// the ordering guarantees are exercised regressively, not just once.
688	func TestConfigSwitchOrderingRegression(t *testing.T) {
689		for _, v := range switchVariants() {
690			t.Run(v.name, func(t *testing.T) {
691				for i := 1; i <= 3; i++ {
692					t.Run(fmt.Sprintf("iteration-%d", i), func(t *testing.T) {
693						upstream := newHoldUpstream(t)
694						cfgA := v.config("A", 201, upstream.addr)
695						cfgB := v.config("B", 202, upstream.addr)
696	
697						tester := caddytest.NewTester(t)
698						tester.InitServer(cfgA, v.configType)
699	
700						client := newSwitchClient(v.h2)
701	
702						// release before commit: the hold completes entirely on A
703						// before B is ever submitted
704						baseHits := upstream.hitCount()
705						hold := startHold(t, client, upstream, v.baseURL, v.wantProto)
706						hold.releaseAndAssertComplete(t)
707						if got := upstream.hitCount() - baseHits; got != 1 {
708							t.Errorf("upstream hits before commit: got %d new, want 1", got)
709						}
710						assertVersion(t, newSwitchProbeClient(v.h2), v.baseURL, versionResponse{status: 201, mark: "A"}, v.wantProto)
711	
712						// the commit after the release still switches cleanly
713						mustLoad(t, cfgB, v.configType)
714						waitForVersion(t, v, versionResponse{status: 202, mark: "B"})
715						assertVersion(t, newSwitchProbeClient(v.h2), v.baseURL, versionResponse{status: 202, mark: "B"}, v.wantProto)
716	
717						// rollback after everything settled: the invalid config is
718						// rejected and B keeps serving without a blip
719						code, body := postLoad(t, invalidSwitchConfig(v.listenAddr), "json")
720						if code == http.StatusOK {
721							t.Fatalf("invalid config with a repeated listener address was accepted")
722						}
723						if !strings.Contains(body, "listener address repeated") {
724							t.Errorf("load error does not report the repeated listener address: %q", body)
725						}
726						assertVersion(t, newSwitchProbeClient(v.h2), v.baseURL, versionResponse{status: 202, mark: "B"}, v.wantProto)
727					})
728				}
729			})
730		}
731	}
